<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rules\Password;
class AuthController extends Controller{public function register(Request $request){$data=$request->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users','password'=>['required','confirmed',Password::min(8)],'graduating_year'=>'required|integer|min:1979|max:'.date('Y'),'phone'=>'nullable|string|max:30','occupation'=>'nullable|string|max:120','location'=>'nullable|string|max:120']);$data['status']='pending';$data['role']='member';$user=User::create($data);return response()->json(['message'=>'Application submitted for verification.','user'=>$user],201);}public function login(Request $request){$data=$request->validate(['email'=>'required|email','password'=>'required']);$user=User::where('email',$data['email'])->first();if(!$user||!Hash::check($data['password'],$user->password))return response()->json(['message'=>'Invalid credentials.'],422);return response()->json(['token'=>$user->createToken('member-portal')->plainTextToken,'user'=>$user]);}public function me(Request $request){return $request->user();}public function logout(Request $request){$request->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Signed out.']);}}
